"use client";

import type { CardBlock } from "@usemoney/types";
import { getIcon } from "@/lib/chat/icon-map";
import { formatCellValue } from "@/lib/chat/format-utils";
import { stripRecommendationLanguage } from "@usemoney/utils/sanitize-recommendation";
import "./chat-blocks.css";

interface CardBlockRendererProps {
  block: CardBlock;
}

/**
 * MONEY-445: chat cards generated by older research runs still carry the
 * BUY/SELL/HOLD recommendation in subtitle / changeLabel / items. We
 * sanitize at render time so existing chat history matches the new
 * informational-only positioning without a DB migration.
 */
const REC_TOKENS = new Set([
  "BUY",
  "STRONG BUY",
  "STRONG_BUY",
  "SELL",
  "STRONG SELL",
  "STRONG_SELL",
  "HOLD",
  "AVOID",
  "NEUTRAL",
  "N/A",
]);

function isRecToken(s: string | undefined | null): boolean {
  if (!s) return false;
  return REC_TOKENS.has(s.trim().toUpperCase());
}

function looksLikeResearchCard(title?: string): boolean {
  if (!title) return false;
  const t = title.toLowerCase();
  return t.includes("research score") || t.includes("research report");
}

function stripRecPrefix(subtitle: string): string {
  const m = subtitle.match(/^(.+?)\s*\|\s*(.+)$/);
  if (!m) return subtitle;
  const first = m[1].trim();
  const rest = m[2].trim();
  if (isRecToken(first) || /Preferred$/i.test(first)) {
    return rest;
  }
  return subtitle;
}

export default function CardBlockRenderer({ block }: CardBlockRendererProps) {
  const IconComponent = getIcon(block.icon);
  const isPositive = (block.change || 0) >= 0;
  const isResearch = looksLikeResearchCard(block.title);

  // MONEY-445: sanitize research card fields
  const stripItemLabels = new Set([
    "recommendation",
    "preferred",
    "price target",
    "confidence",
  ]);
  const visibleItems =
    block.items && isResearch
      ? block.items.filter(
          (i) => !stripItemLabels.has(i.label.trim().toLowerCase())
        )
      : block.items;

  const cleanSubtitle = block.subtitle
    ? stripRecommendationLanguage(
        isResearch ? stripRecPrefix(block.subtitle) : block.subtitle
      )
    : block.subtitle;
  const cleanValue = block.value
    ? stripRecommendationLanguage(block.value)
    : block.value;
  const cleanChangeLabel =
    isResearch && isRecToken(block.changeLabel || "")
      ? undefined
      : block.changeLabel
        ? stripRecommendationLanguage(block.changeLabel)
        : block.changeLabel;
  const showChange = !isResearch && block.change !== undefined;

  return (
    <div className="cb-card" style={{ padding: 16, margin: "6px 0" }}>
      {/* Header row */}
      <div className="cb-card-head">
        <span className="cb-card-title">{block.title}</span>
        {IconComponent && (
          <IconComponent
            style={{
              width: 16,
              height: 16,
              color: "var(--ink-3)",
              flexShrink: 0,
            }}
          />
        )}
      </div>

      {/* Value */}
      {cleanValue && <div className="cb-card-value">{cleanValue}</div>}

      {/* Subtitle */}
      {cleanSubtitle && <div className="cb-card-subtitle">{cleanSubtitle}</div>}

      {/* Change indicator — numbers only, no buy/sell language */}
      {showChange && (
        <div className={`cb-card-change ${isPositive ? "pos" : "neg"}`}>
          <span>{isPositive ? "▲" : "▼"}</span>
          <span>
            {isPositive ? "+" : ""}
            {(block.change as number).toFixed(2)}%
          </span>
          {cleanChangeLabel && (
            <span
              style={{
                fontFamily: "inherit",
                fontSize: 11.5,
                color: "var(--ink-3)",
                marginLeft: 4,
                fontWeight: 500,
              }}
            >
              {cleanChangeLabel}
            </span>
          )}
        </div>
      )}

      {/* Items grid */}
      {visibleItems && visibleItems.length > 0 && (
        <div className="cb-card-items">
          {visibleItems.map((item, index) => {
            const { text, colorClass } = formatCellValue(
              item.value,
              item.format
            );
            return (
              <div key={index} className="cb-card-item">
                <span className="cb-card-item-label">{item.label}</span>
                <span
                  className="cb-card-item-value"
                  style={
                    colorClass?.includes("emerald")
                      ? { color: "var(--emerald-text)" }
                      : colorClass?.includes("red")
                        ? { color: "var(--pop-1-text)" }
                        : undefined
                  }
                >
                  {text}
                </span>
              </div>
            );
          })}
        </div>
      )}

      {/* Research disclaimer */}
      {isResearch && (
        <div className="cb-disclaimer">
          AI-generated analysis for informational purposes only. Not financial
          advice. UseMoney is not a SEBI-registered Research Analyst or
          Investment Advisor. Consult a SEBI-registered advisor before acting on
          any of this content.
        </div>
      )}
    </div>
  );
}
